    let mut taken = Vec::new();
    for (at, (file, table)) in files.iter().zip(&tables).enumerate() {
        let keys: Vec<&str> = start
            .keys()
            .filter(|key| table.contains_key(*key))
            .filter(|key| !tables[at + 1..].iter().any(|later| later.contains_key(*key)))
